[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>GlobalStone — Global Commercial Real Estate Services</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --navy: #0A1628;
      --navy-light: #1a2744;
      --white: #ffffff;
      --gray-100: #f8f9fa;
      --gray-200: #e9ecef;
      --gray-300: #dee2e6;
      --gray-400: #ced4da;
      --gray-500: #adb5bd;
      --gray-600: #6c757d;
      --gray-700: #495057;
      --gray-800: #343a40;
      --gold: #c9a962;
      --gold-light: #d4b978;
      --teal: #0d7377;
      --teal-light: #14919b;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--gray-800);
      background-color: var(--white);
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    img {
      max-width: 100%;
      height: auto;
    }

    /* Header & Navigation */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: var(--navy);
      transition: background 0.3s ease;
    }

    .header-inner {
      max-width: 1400px;
      margin: 0 auto;
      padding: 0 40px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 80px;
    }

    .logo {
      font-size: 24px;
      font-weight: 700;
      color: var(--white);
      letter-spacing: -0.5px;
    }

    .logo span {
      color: var(--gold);
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 40px;
    }

    .nav-link {
      color: var(--gray-300);
      font-size: 14px;
      font-weight: 500;
      padding: 8px 0;
      position: relative;
      cursor: pointer;
      transition: color 0.2s ease;
    }

    .nav-link:hover {
      color: var(--white);
    }

    .nav-link-services {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .nav-link-services::after {
      content: '';
      width: 0;
      height: 0;
      border-left: 4px solid transparent;
      border-right: 4px solid transparent;
      border-top: 4px solid currentColor;
      margin-top: 2px;
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      min-width: 600px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.3);
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s ease, visibility 0.3s ease;
      padding: 40px;
      display: flex;
      gap: 60px;
    }

    .nav-item-services:hover .mega-menu,
    .mega-menu:hover {
      opacity: 1;
      visibility: visible;
    }

    .mega-menu-column h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--gray-500);
      margin-bottom: 16px;
    }

    .mega-menu-column ul {
      list-style: none;
    }

    .mega-menu-column li {
      margin-bottom: 12px;
    }

    .mega-menu-column a {
      font-size: 14px;
      font-weight: 500;
      color: var(--navy);
      transition: color 0.2s ease;
    }

    .mega-menu-column a:hover {
      color: var(--teal);
    }

    /* Mobile Menu */
    .mobile-toggle {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      padding: 10px;
    }

    .mobile-toggle span {
      width: 24px;
      height: 2px;
      background: var(--white);
      transition: transform 0.3s ease;
    }

    .nav-mobile {
      display: none;
      position: fixed;
      top: 80px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--navy);
      overflow-y: auto;
    }

    .nav-mobile.active {
      display: block;
    }

    .mobile-nav-section {
      border-bottom: 1px solid var(--gray-700);
    }

    .mobile-nav-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 20px;
      color: var(--white);
      font-weight: 500;
      cursor: pointer;
    }

    .mobile-nav-header::after {
      content: '+';
      font-size: 20px;
    }

    .mobile-nav-header.active::after {
      content: '−';
    }

    .mobile-nav-content {
      display: none;
      padding: 0 20px 20px;
    }

    .mobile-nav-content.active {
      display: block;
    }

    .mobile-nav-content a {
      display: block;
      padding: 12px 0;
      color: var(--gray-400);
      font-size: 14px;
    }

    /* Hero Section */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      background: linear-gradient(135deg, var(--navy) 0%, #0f1f3a 100%);
      overflow: hidden;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800"><rect fill="%230A1628"/><g fill="%23ffffff" opacity="0.03"><rect x="100" y="500" width="80" height="300"/><rect x="200" y="400" width="60" height="400"/><rect x="300" y="550" width="100" height="250"/><rect x="450" y="300" width="70" height="500"/><rect x="550" y="450" width="90" height="350"/><rect x="700" y="350" width="60" height="450"/><rect x="800" y="500" width="80" height="300"/><rect x="900" y="400" width="100" height="400"/><rect x="1000" y="480" width="70" height="320"/></g></svg>') center/cover;
      opacity: 0.5;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 1400px;
      margin: 0 auto;
      padding: 120px 40px 80px;
      width: 100%;
    }

    .hero-label {
      display: inline-block;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--gold);
      margin-bottom: 24px;
    }

    .hero-title {
      font-size: clamp(36px, 5vw, 64px);
      font-weight: 700;
      color: var(--white);
      line-height: 1.1;
      max-width: 800px;
      margin-bottom: 24px;
    }

    .hero-subtitle {
      font-size: 18px;
      color: var(--gray-400);
      max-width: 600px;
      margin-bottom: 40px;
      line-height: 1.7;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 16px 32px;
      font-size: 14px;
      font-weight: 600;
      border-radius: 4px;
      cursor: pointer;
      transition: all 0.2s ease;
      border: none;
    }

    .btn-primary {
      background: var(--gold);
      color: var(--navy);
    }

    .btn-primary:hover {
      background: var(--gold-light);
      transform: translateY(-2px);
    }

    .btn-secondary {
      background: transparent;
      color: var(--white);
      border: 1px solid var(--gray-600);
    }

    .btn-secondary:hover {
      border-color: var(--white);
    }

    .btn-outline {
      background: transparent;
      color: var(--navy);
      border: 1px solid var(--navy);
    }

    .btn-outline:hover {
      background: var(--navy);
      color: var(--white);
    }

    /* Announcement Banner */
    .announcement {
      background: var(--teal);
      padding: 16px 40px;
      text-align: center;
    }

    .announcement-inner {
      max-width: 1400px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 20px;
      flex-wrap: wrap;
    }

    .announcement-text {
      color: var(--white);
      font-weight: 500;
    }

    .announcement .btn {
      padding: 10px 20px;
      font-size: 13px;
      background: var(--white);
      color: var(--teal);
    }

    .announcement .btn:hover {
      background: var(--gray-100);
    }

    /* About Statement */
    .about-statement {
      padding: 120px 40px;
      text-align: center;
      background: var(--white);
    }

    .about-statement-inner {
      max-width: 900px;
      margin: 0 auto;
    }

    .section-label {
      display: inline-block;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--gold);
      margin-bottom: 20px;
    }

    .about-statement h2 {
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 600;
      color: var(--navy);
      line-height: 1.3;
      margin-bottom: 24px;
    }

    .about-statement p {
      font-size: 18px;
      color: var(--gray-600);
      line-height: 1.8;
      margin-bottom: 32px;
    }

    /* What We Do Section */
    .what-we-do {
      display: flex;
      background: var(--gray-100);
    }

    .what-we-do-tabs {
      width: 300px;
      flex-shrink: 0;
      background: var(--navy);
      padding: 60px 40px;
    }

    .what-we-do-tab {
      padding: 20px;
      cursor: pointer;
      border-bottom: 1px solid var(--gray-700);
      transition: all 0.3s ease;
    }

    .what-we-do-tab:last-child {
      border-bottom: none;
    }

    .what-we-do-tab h4 {
      font-size: 16px;
      font-weight: 600;
      color: var(--gray-500);
      margin-bottom: 8px;
      transition: color 0.3s ease;
    }

    .what-we-do-tab p {
      font-size: 13px;
      color: var(--gray-600);
      opacity: 0;
      max-height: 0;
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .what-we-do-tab.active h4 {
      color: var(--gold);
    }

    .what-we-do-tab.active p {
      opacity: 1;
      max-height: 100px;
      margin-top: 12px;
    }

    .what-we-do-content {
      flex: 1;
      padding: 60px;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .what-we-do-panel {
      display: none;
    }

    .what-we-do-panel.active {
      display: block;
    }

    .what-we-do-panel h3 {
      font-size: 32px;
      font-weight: 600;
      color: var(--navy);
      margin-bottom: 16px;
    }

    .what-we-do-panel p {
      font-size: 16px;
      color: var(--gray-600);
      line-height: 1.8;
      margin-bottom: 24px;
      max-width: 600px;
    }

    /* Services Preview */
    .services-preview {
      padding: 120px 40px;
      background: var(--white);
    }

    .section-header {
      text-align: center;
      margin-bottom: 60px;
    }

    .section-header h2 {
      font-size: clamp(28px, 4vw, 40px);
      font-weight: 600;
      color: var(--navy);
      margin-bottom: 16px;
    }

    .section-header p {
      font-size: 16px;
      color: var(--gray-600);
      max-width: 600px;
      margin: 0 auto;
    }

    .services-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 30px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .service-card {
      padding: 40px;
      background: var(--gray-100);
      border-radius: 8px;
      transition: all 0.3s ease;
    }

    .service-card:hover {
      background: var(--navy);
    }

    .service-card:hover h3,
    .service-card:hover p {
      color: var(--white);
    }

    .service-card:hover .service-link {
      color: var(--gold);
    }

    .service-card h3 {
      font-size: 20px;
      font-weight: 600;
      color: var(--navy);
      margin-bottom: 12px;
      transition: color 0.3s ease;
    }

    .service-card p {
      font-size: 14px;
      color: var(--gray-600);
      line-height: 1.7;
      margin-bottom: 20px;
      transition: color 0.3s ease;
    }

    .service-link {
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      display: inline-flex;
      align-items: center;
      gap: 6px;
      transition: color 0.3s ease;
    }

    .service-link::after {
      content: '→';
    }

    /* Newsletter Section */
    .newsletter {
      padding: 100px 40px;
      background: var(--navy);
      text-align: center;
    }

    .newsletter-inner {
      max-width: 600px;
      margin: 0 auto;
    }

    .newsletter h3 {
      font-size: 32px;
      font-weight: 600;
      color: var(--white);
      margin-bottom: 12px;
    }

    .newsletter p {
      font-size: 16px;
      color: var(--gray-400);
      margin-bottom: 32px;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 500px;
      margin: 0 auto;
    }

    .newsletter-form input {
      flex: 1;
      padding: 16px 20px;
      border: none;
      border-radius: 4px;
      font-size: 14px;
      background: var(--white);
    }

    .newsletter-form input::placeholder {
      color: var(--gray-500);
    }

    .newsletter-form button {
      padding: 16px 32px;
      background: var(--gold);
      color: var(--navy);
      font-weight: 600;
      font-size: 14px;
      border: none;
      border-radius: 4px;
      cursor: pointer;
      transition: background 0.2s ease;
    }

    .newsletter-form button:hover {
      background: var(--gold-light);
    }

    /* Latest Insights */
    .latest-insights {
      padding: 120px 40px;
      background: var(--gray-100);
    }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 30px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .insight-card {
      background: var(--white);
      border-radius: 8px;
      overflow: hidden;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .insight-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.1);
    }

    .insight-image {
      height: 200px;
      background: linear-gradient(135deg, var(--teal) 0%, var(--navy) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .insight-image span {
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      padding: 20px;
      text-align: center;
    }

    .insight-content {
      padding: 30px;
    }

    .insight-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--teal);
      background: var(--gray-100);
      padding: 6px 12px;
      border-radius: 4px;
      margin-bottom: 16px;
    }

    .insight-content h4 {
      font-size: 18px;
      font-weight: 600;
      color: var(--navy);
      line-height: 1.4;
      margin-bottom: 8px;
    }

    .insight-content p {
      font-size: 13px;
      color: var(--gray-500);
    }

    /* Our Commitment */
    .our-commitment {
      padding: 120px 40px;
      background: var(--white);
    }

    .commitment-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 40px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .commitment-card {
      text-align: center;
      padding: 40px 20px;
    }

    .commitment-icon {
      width: 64px;
      height: 64px;
      background: var(--gray-100);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
      font-size: 24px;
    }

    .commitment-card h4 {
      font-size: 18px;
      font-weight: 600;
      color: var(--navy);
      margin-bottom: 12px;
    }

    .commitment-card p {
      font-size: 14px;
      color: var(--gray-600);
      line-height: 1.7;
      margin-bottom: 20px;
    }

    .commitment-link {
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
    }

    /* Featured Insights */
    .featured-insights {
      padding: 100px 40px;
      background: var(--white);
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 30px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .featured-card {
      padding: 30px;
      background: var(--gray-100);
      border-radius: 8px;
      display: flex;
      gap: 20px;
      align-items: flex-start;
      transition: background 0.3s ease;
    }

    .featured-card:hover {
      background: var(--navy);
    }

    .featured-card:hover * {
      color: var(--white);
    }

    .featured-type {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--gold);
      margin-bottom: 8px;
    }

    .featured-card h4 {
      font-size: 16px;
      font-weight: 600;
      color: var(--navy);
      line-height: 1.4;
      transition: color 0.3s ease;
    }

    /* Footer */
    .footer {
      background: var(--navy);
      padding: 80px 40px 40px;
    }

    .footer-inner {
      max-width: 1400px;
      margin: 0 auto;
    }

    .footer-main {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 60px;
      margin-bottom: 60px;
    }

    .footer-brand p {
      color: var(--gray-500);
      font-size: 14px;
      line-height: 1.7;
      margin-top: 20px;
      max-width: 300px;
    }

    .footer-column h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--gray-500);
      margin-bottom: 20px;
    }

    .footer-column ul {
      list-style: none;
    }

    .footer-column li {
      margin-bottom: 12px;
    }

    .footer-column a {
      font-size: 14px;
      color: var(--gray-400);
      transition: color 0.2s ease;
    }

    .footer-column a:hover {
      color: var(--white);
    }

    .footer-bottom {
      border-top: 1px solid var(--gray-700);
      padding-top: 30px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 20px;
    }

    .footer-legal {
      display: flex;
      gap: 30px;
    }

    .footer-legal a {
      font-size: 13px;
      color: var(--gray-600);
    }

    .footer-legal a:hover {
      color: var(--white);
    }

    .footer-copyright {
      font-size: 13px;
      color: var(--gray-600);
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .nav-desktop {
        display: none;
      }

      .mobile-toggle {
        display: flex;
      }

      .what-we-do {
        flex-direction: column;
      }

      .what-we-do-tabs {
        width: 100%;
        padding: 20px;
        display: flex;
        overflow-x: auto;
        gap: 0;
      }

      .what-we-do-tab {
        padding: 16px 20px;
        border-bottom: none;
        border-right: 1px solid var(--gray-700);
        min-width: 150px;
      }

      .what-we-do-tab:last-child {
        border-right: none;
      }

      .what-we-do-tab h4 {
        font-size: 14px;
        margin-bottom: 0;
      }

      .what-we-do-content {
        padding: 40px 20px;
      }

      .footer-main {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .header-inner {
        padding: 0 20px;
        height: 70px;
      }

      .hero-content {
        padding: 100px 20px 60px;
      }

      .announcement {
        padding: 14px 20px;
      }

      .about-statement,
      .services-preview,
      .latest-insights,
      .our-commitment,
      .featured-insights {
        padding: 80px 20px;
      }

      .newsletter {
        padding: 60px 20px;
      }

      .newsletter-form {
        flex-direction: column;
      }

      .footer {
        padding: 60px 20px 30px;
      }

      .footer-main {
        grid-template-columns: 1fr;
        gap: 40px;
      }

      .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
      }

      .footer-legal {
        flex-direction: column;
        gap: 12px;
      }
    }
  </style>
</head>
<body>
  <!-- Header -->
  <header class="header">
    <div class="header-inner">
      <a href="index.html" class="logo">Global<span>Stone</span></a>
      <nav class="nav-desktop">
        <div class="nav-item nav-item-services">
          <span class="nav-link nav-link-services">Services</span>
          <div class="mega-menu">
            <div class="mega-menu-column">
              <h4>By Need</h4>
              <ul>
                <li><a href="services-invest-finance-value.html">Invest, Finance & Value</a></li>
                <li><a href="services-plan-lease-occupy.html">Plan, Lease & Occupy</a></li>
                <li><a href="services-design-build.html">Design & Build</a></li>
                <li><a href="services.html">Manage Properties & Portfolios</a></li>
                <li><a href="services.html">Transform Business Outcomes</a></li>
              </ul>
            </div>
            <div class="mega-menu-column">
              <h4>By Property Type</h4>
              <ul>
                <li><a href="services.html">Office</a></li>
